// ================= CONFIG (ajuste para a sua tabela real) =================
const TABELA   = 'rfs_faturados';      // nome da tabela do banco de RFs
const COL_RF   = 'rf';                 // coluna que guarda o numero do RF (PRIMARY KEY)
const COL_REF  = 'rf';                 // referencia exibida no front: o proprio RF
const COL_TIPO = '';                   // sem coluna de tipo nesta tabela
// ==========================================================================

const body   = $json.body ?? $json;
const tipo   = String(body.tipo_faturamento ?? 'VALE').trim();
const brutos = Array.isArray(body.rfs) ? body.rfs : [];

// Mesma normalizacao do front (conferencia_rf.normalizar_rf):
// string, sem espacos nas pontas e sem sufixo '.0' de floats do Excel.
const normalizar = (v) => {
  if (v === null || v === undefined) return '';
  let t = String(v).trim();
  if (/^\d+\.0$/.test(t)) t = t.slice(0, -2);
  return t;
};

const rfs = [...new Set(brutos.map(normalizar).filter(Boolean))];

let sql = '';
if (rfs.length) {
  const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "''");
  const lista = rfs.map((r) => `'${esc(r)}'`).join(',');
  sql = `SELECT ${COL_RF} AS rf, ${COL_REF} AS linha FROM ${TABELA} WHERE ${COL_RF} IN (${lista})`;
  if (COL_TIPO) sql += ` AND ${COL_TIPO} = '${esc(tipo)}'`;
}

return [{ json: { tipo_faturamento: tipo, rfs, sql } }];

// Converte o resultado do MySQL no formato que o front espera:
// { "existentes": [ { "rf": "...", "linha": <referencia no banco> } ] }
const existentes = $input
  .all()
  .map((i) => i.json)
  .filter((j) => j && j.rf !== undefined && j.rf !== null)
  .map((j) => ({ rf: String(j.rf), linha: j.linha ?? '-' }));

return [{ json: { existentes } }];
